-- Import of client-confirmed product selection (status OSTAJE) from
-- 'Copy of PE-LINE web - odabir proizvoda.xlsx', confirmed 2026-10-09.
-- 214 products: bojleri 3, dimovodi 50, instalacije 22, ormarici 25, podno-grijanje 45, radijatori 23, regulacije 13, spremnici 19, ventilokonvektori 14
-- Generated file — regenerate from the spreadsheet instead of editing by hand.

-- Root category, only when no category tree exists yet (site lists children of a root).
insert into categories (name_hr, name_sl, name_en, slug, sort_order)
select 'Proizvodi', 'Izdelki', 'Products', 'proizvodi', 0
where not exists (select 1 from categories where parent_id is not null)
on conflict (slug) do nothing;

-- Site categories; new ones join the same parent as the existing ones.
with root as (
  select coalesce(
    (select parent_id from categories where parent_id is not null order by sort_order limit 1),
    (select id from categories where slug = 'proizvodi')
  ) as id
)
insert into categories (name_hr, name_sl, name_en, slug, icon, sort_order, description_hr, parent_id)
select v.name_hr, v.name_sl, v.name_en, v.slug, v.icon, v.sort_order, v.description_hr, root.id
from root, (values
  ('Dimovodi', 'Dimovodi', 'Flue pipes', 'dimovodi', 'Flame', 1, null),
  ('Ormarići', 'Omarice', 'Cabinets', 'ormarici', 'Columns3', 2, null),
  ('Podno grijanje', 'Talno ogrevanje', 'Underfloor heating', 'podno-grijanje', 'Layers', 3, null),
  ('Radijatori', 'Radiatorji', 'Radiators', 'radijatori', 'Thermometer', 4, null),
  ('Regulacije', 'Regulacije', 'Controls', 'regulacije', 'Settings', 5, null),
  ('Spremnici', 'Zbiralniki', 'Tanks', 'spremnici', 'Box', 6, null),
  ('Ventilokonvektori', 'Ventilatorski konvektorji', 'Fan coil units', 'ventilokonvektori', 'Wind', 7, null),
  ('Bojleri i kotlovi', 'Grelniki vode in kotli', 'Water heaters and boilers', 'bojleri', 'Flame', 8, 'Električni bojleri i kotlovi za pripremu potrošne tople vode i grijanje.'),
  ('Instalacije', 'Instalacije', 'Installations', 'instalacije', 'SlidersHorizontal', 9, 'Armature, ventili, razdjelnici i ostala oprema za instalacije grijanja.')
) as v(name_hr, name_sl, name_en, slug, icon, sort_order, description_hr)
on conflict (slug) do nothing;

